import type {CompletionContext, CompletionResult} from '@codemirror/autocomplete'
import {hoverTooltip, type EditorView} from '@codemirror/view'
import {linter} from '@github-ui/code-mirror/linter'
import {getRange} from '@github-ui/code-mirror/utils'
import {featureFlag} from '@github-ui/feature-flags'
import {autocomplete} from '../autocomplete-util'
import {
  buildCompletions,
  yamlAutocomplete,
  yamlAutocompleteLanguageService,
  yamlHelpPanel,
} from '../codemirror-next-autocomplete-util'
import {getRootRule as getWorkflowRootRule} from './workflow-rules'
import {buildLintMarks} from '../../codemirror-next-linter-util'
import lint from '../yaml-linters'

// Lazy-loaded language service module (only when feature flag is enabled)
// Using a promise to prevent duplicate imports if called concurrently
let languageServicePromise: Promise<typeof import('./workflow-editor-language-service')> | null = null

async function getLanguageServiceModule() {
  if (!languageServicePromise) {
    languageServicePromise = import('./workflow-editor-language-service')
  }
  return languageServicePromise
}

// Capture feature flag state once at module load to ensure consistent behavior
const useLanguageService = featureFlag.isFeatureEnabled('actions_workflow_language_service')

export function workflowEditor() {
  // Use different autocomplete behavior based on feature flag:
  // - Language service: don't auto-trigger next completion (user must Ctrl+Space)
  // - Rules-based: auto-trigger for snippet placeholders
  const autocompleteExtension = useLanguageService
    ? yamlAutocompleteLanguageService(workflowAutocompleteContext)
    : yamlAutocomplete(workflowAutocompleteContext)

  const extensions = [autocompleteExtension, yamlHelpPanel(), linter(workflowYamlLintSource)]

  // Only add hover support when language service is enabled
  if (useLanguageService) {
    extensions.push(hoverTooltip(workflowHoverSource))
  }

  return extensions
}

async function workflowAutocompleteContext(context: CompletionContext): Promise<CompletionResult | null> {
  if (!context.explicit) return null

  // Use new language service if feature flag is enabled
  if (useLanguageService) {
    const module = await getLanguageServiceModule()
    return module.workflowAutocompleteContextWithLanguageService(context)
  }

  // Fallback to existing implementation
  const cursor = context.pos
  const textBeforeCursor = getRange(context.state, 0, cursor)

  const suggestions = await autocomplete(
    context.state.doc.toString(),
    textBeforeCursor,
    getWorkflowRootRule,
    getWorkflowRootRule({}).suggestionsForExpression!,
  )

  if (!suggestions) {
    return null
  }

  return buildCompletions(suggestions, cursor)
}

async function workflowYamlLintSource(view: EditorView) {
  // Use new language service if feature flag is enabled
  if (useLanguageService) {
    const module = await getLanguageServiceModule()
    return module.workflowYamlLintSourceWithLanguageService(view)
  }

  // Fallback to existing implementation
  const annotations = await lint(view.state.doc.toString(), getWorkflowRootRule)

  return buildLintMarks(view, annotations)
}

async function workflowHoverSource(view: EditorView, pos: number, _side: -1 | 1) {
  const module = await getLanguageServiceModule()
  const result = await module.workflowHoverWithLanguageService(view, pos)

  if (!result) {
    return null
  }

  return {
    pos: result.pos,
    end: result.end,
    above: true,
    create: () => ({dom: result.dom}),
  }
}
